import csv, math, statistics
from collections import defaultdict

def read(f):
    with open(f, newline='') as fh:
        return list(csv.reader(fh))

files = ['ae_ip_termination_by_month.csv','ae_ip_termination.csv','ae_ci_age_gender.csv','ae_death_age_gender.csv','ae_tpd_age_gender.csv','ae_ip_age_gender.csv']
for f in files:
    try:
        rows=read(f)
    except Exception as e:
        print('MISSING',f,repr(e)); continue
    print('===',f,'rows',len(rows))
    if rows:
        print('header',rows[0])
        print('first5')
        for r in rows[1:6]: print(r)
        print('last5')
        for r in rows[-5:]: print(r)
        # try find AE column numeric
        hdr=rows[0]
        ae_idx=None
        for i,h in enumerate(hdr):
            if 'AE' in h.upper() or 'ae' in h.lower(): ae_idx=i
        if ae_idx is not None:
            vals=[]
            for r in rows[1:]:
                try:
                    v=float(r[ae_idx])
                    vals.append((abs(v-1.0), r))
                except: pass
            vals.sort(reverse=True)
            print('top extreme AE rows (by |AE-1|):')
            for v,r in vals[:10]:
                print(v, r)
